ALTER TABLE public.gyms ALTER COLUMN user_id DROP NOT NULL;
ALTER TABLE public.exercises ALTER COLUMN user_id DROP NOT NULL;
ALTER TABLE public.gyms ADD COLUMN is_default boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX gyms_one_default ON public.gyms(is_default) WHERE is_default;
INSERT INTO public.gyms(name,description,is_public,is_default) VALUES ('Gymmet','All equipment available.',true,true);
INSERT INTO public.gym_equipment(gym_id,equipment_id) SELECT g.id,e.id FROM public.gyms g CROSS JOIN public.exercise_equipment e WHERE g.is_default ON CONFLICT DO NOTHING;
CREATE FUNCTION public.default_gym_equipment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.gym_equipment(gym_id,equipment_id) SELECT id,NEW.id FROM public.gyms WHERE is_default ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER default_gym_equipment AFTER INSERT ON public.exercise_equipment FOR EACH ROW EXECUTE FUNCTION public.default_gym_equipment();
CREATE TABLE public.user_memberships (user_id uuid PRIMARY KEY,tier_id text NOT NULL REFERENCES public.ai_tiers(id) ON DELETE RESTRICT,starts_on date NOT NULL,ends_on date NOT NULL,stripe_reference text UNIQUE,verified_by uuid NOT NULL,verified_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT membership_dates CHECK(ends_on>=starts_on));
GRANT SELECT ON public.user_memberships TO authenticated;
GRANT ALL ON public.user_memberships TO service_role;
ALTER TABLE public.user_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY memberships_read ON public.user_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.has_supporter_access(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR EXISTS(SELECT 1 FROM public.user_memberships WHERE user_id=_user_id AND tier_id='supporter' AND current_date BETWEEN starts_on AND ends_on) $$;
REVOKE ALL ON FUNCTION public.has_supporter_access(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_supporter_access(uuid) TO authenticated,service_role;
CREATE POLICY owner_create_location ON public.gyms FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT is_public AND NOT is_default AND public.has_supporter_access(auth.uid()) AND NOT public.user_view_active());
CREATE POLICY owner_update_location ON public.gyms FOR UPDATE TO authenticated USING(user_id=auth.uid() AND NOT is_public AND NOT is_default AND public.has_supporter_access(auth.uid()) AND NOT public.user_view_active()) WITH CHECK(user_id=auth.uid() AND NOT is_public AND NOT is_default);
CREATE POLICY owner_delete_location ON public.gyms FOR DELETE TO authenticated USING(user_id=auth.uid() AND NOT is_public AND NOT is_default AND NOT public.user_view_active());
CREATE POLICY owner_insert_equipment ON public.gym_equipment FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.gyms WHERE id=gym_id AND user_id=auth.uid() AND NOT is_public AND public.has_supporter_access(auth.uid())) AND NOT public.user_view_active());
CREATE POLICY owner_delete_equipment ON public.gym_equipment FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.gyms WHERE id=gym_id AND user_id=auth.uid() AND NOT is_public) AND NOT public.user_view_active());
CREATE POLICY owner_update_equipment ON public.gym_equipment FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.gyms WHERE id=gym_id AND user_id=auth.uid() AND NOT is_public AND public.has_supporter_access(auth.uid())) AND NOT public.user_view_active()) WITH CHECK(EXISTS(SELECT 1 FROM public.gyms WHERE id=gym_id AND user_id=auth.uid() AND NOT is_public));
CREATE FUNCTION public.set_manual_membership(_user_id uuid,_starts_on date,_ends_on date,_stripe_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR public.user_view_active() THEN RAISE EXCEPTION 'Forbidden'; END IF; IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=_user_id) THEN RAISE EXCEPTION 'Unknown user'; END IF; IF _ends_on<_starts_on OR _starts_on>current_date OR length(trim(_stripe_reference))<3 OR length(_stripe_reference)>255 THEN RAISE EXCEPTION 'Invalid membership'; END IF; INSERT INTO public.user_memberships(user_id,tier_id,starts_on,ends_on,stripe_reference,verified_by) VALUES(_user_id,'supporter',_starts_on,_ends_on,trim(_stripe_reference),auth.uid()) ON CONFLICT(user_id) DO UPDATE SET starts_on=excluded.starts_on,ends_on=excluded.ends_on,stripe_reference=excluded.stripe_reference,verified_by=excluded.verified_by,verified_at=now(); INSERT INTO public.user_ai_quotas(user_id,tier_id,valid_until,updated_by) VALUES(_user_id,'supporter',_ends_on,auth.uid()) ON CONFLICT(user_id) DO UPDATE SET tier_id='supporter',valid_until=excluded.valid_until,updated_by=excluded.updated_by,updated_at=now(); END $$;
REVOKE ALL ON FUNCTION public.set_manual_membership(uuid,date,date,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_manual_membership(uuid,date,date,text) TO authenticated;
CREATE FUNCTION public.public_exercise_catalogue() RETURNS TABLE(id uuid,code text,name text,instructions text,reps_unit text,category text,equipment text,image_urls jsonb) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e.id,e.code,e.name,e.instructions,e.reps_unit,c.name,coalesce(q.name,''),e.image_urls FROM public.exercises e JOIN public.exercise_categories c ON c.id=e.category_id LEFT JOIN public.exercise_equipment q ON q.id=e.equipment_id WHERE e.is_active ORDER BY c.sort_order,e.code_number $$;
REVOKE ALL ON FUNCTION public.public_exercise_catalogue() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_exercise_catalogue() TO anon,authenticated,service_role;
CREATE POLICY public_catalogue_images ON storage.objects FOR SELECT TO anon USING(bucket_id='exercise-images' AND public.is_exercise_image(name));
CREATE FUNCTION public.erase_account_data(_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
DELETE FROM public.log_entries WHERE user_id=_user_id;
DELETE FROM public.workouts WHERE user_id=_user_id;
DELETE FROM public.training_ai_history WHERE user_id=_user_id;
DELETE FROM public.training_profiles WHERE user_id=_user_id;
DELETE FROM public.training_goals WHERE user_id=_user_id;
DELETE FROM public.user_exercise_preferences WHERE user_id=_user_id;
DELETE FROM public.user_consents WHERE user_id=_user_id;
DELETE FROM public.user_ai_quotas WHERE user_id=_user_id;
DELETE FROM public.user_memberships WHERE user_id=_user_id;
DELETE FROM public.exercise_suggestions WHERE user_id=_user_id;
DELETE FROM public.support_messages WHERE user_id=_user_id;
DELETE FROM public.exercise_locations WHERE user_id=_user_id;
DELETE FROM public.admin_user_views WHERE actor_id=_user_id OR target_user_id=_user_id;
UPDATE public.exercises SET user_id=NULL WHERE user_id=_user_id;
DELETE FROM public.gyms WHERE user_id=_user_id AND NOT is_public;
UPDATE public.gyms SET user_id=NULL WHERE user_id=_user_id;
END $$;
REVOKE ALL ON FUNCTION public.erase_account_data(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.erase_account_data(uuid) TO service_role;